Definition pr_chk (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) (BLi BLj : CA.blocks) : option CH2.cinfo :=
  let regs := CA.ps_reglist ps in
  if (expr_eqb (nth 10 regs (ELit 0)) BUFE && expr_eqb (nth 11 regs (ELit 0)) (EVar 33) && expr_eqb (nth 12 regs (ELit 0)) KE && expr_eqb (nth 13 regs (ELit 0)) (ELit (2 ^ 64 - 4)) &&
      expr_eqb (nth 14 regs (ELit 0)) (ELit 17) && expr_eqb (nth 15 regs (ELit 0)) (EVar 11) && expr_eqb (nth 2 regs (ELit 0)) SPE &&
      CC.has_cell (SR.ps_cells ps) (KWord (SA (EVar 11) 0) 8 (EVar 32)) && CC.has_cell (SR.ps_cells ps) (KUnk (SA (EVar 2) (-144)) (ELit 104)))%bool
  then FXK.strans_chkN GT.NF G.HDECL S2E 0 PR_SCR None c ps cj BLi BLj else None.
